def met(q, what): return ["https://www.metmuseum.org/art/collection/search?q=" + q, "The Met collection: " + q.replace("+", " "), what]
def vam(q, what): return ["https://collections.vam.ac.uk/search/?q=" + q, "V&A collections: " + q.replace("+", " "), what]
def bm(q, what): return ["https://www.britishmuseum.org/collection/search?keyword=" + q, "British Museum collection: " + q.replace("+", " "), what]
def aic(q, what): return ["https://www.artic.edu/collection?q=" + q, "Art Institute of Chicago: " + q.replace("+", " "), what]
def tate(q, what): return ["https://www.tate.org.uk/search?q=" + q, "Tate collection: " + q.replace("+", " "), what]
def si(q, what): return ["https://collections.si.edu/search/results.htm?q=" + q, "Smithsonian collections (incl. Freer|Sackler): " + q.replace("+", " "), what]
